1	"use client";
2	
3	import { useCallback, useEffect, useRef, useState, useTransition } from "react";
4	import type {
5	  MailFolder,
6	  MailboxInfo,
7	  ListResult,
8	  MessageSummary,
9	  MessageFull,
10	  SendPayload,
11	} from "@/lib/mail/types";
12	import {
13	  listFolders,
14	  listMessages,
15	  getMessage,
16	  getMailboxes,
17	  sendMessage,
18	  setFlag,
19	  moveMessage,
20	  deleteMessage,
21	} from "@/lib/actions-mail";
22	import { getMailboxSettings } from "@/lib/actions-mailbox-settings";
23	import { FolderRail, MiniRail, type RailItem } from "./FolderRail";
24	import { MessageList } from "./MessageList";
25	import { ReadingPane } from "./ReadingPane";
26	import { ContactPanel } from "./ContactPanel";
27	import { Composer, type ComposeDraft } from "./Composer";
28	import { MailSettings } from "./MailSettings";
29	import { ShortcutHelp } from "./ShortcutHelp";
30	import { Icon, displayName, categoryOf, type MailTab } from "./util";
31	
32	const STARRED = "__starred__";
33	const SNOOZED = "__snoozed__";
34	
35	/** Per-mailbox signature config used when composing. */
36	type SigConfig = {
37	  enabled: boolean;
38	  onReply: boolean;
39	  placement: "above" | "below";
40	  plain: string; // plain-text fallback / derived text part
41	  html: string; // sanitized rich-signature HTML
42	};
43	
44	const ROLE_META: Record<string, { label: string; icon: RailItem["icon"]; order: number }> = {
45	  inbox: { label: "Inbox", icon: "inbox", order: 0 },
46	  sent: { label: "Sent", icon: "sent", order: 3 },
47	  drafts: { label: "Drafts", icon: "draft", order: 4 },
48	  junk: { label: "Spam", icon: "spam", order: 5 },
49	  trash: { label: "Trash", icon: "trash", order: 6 },
50	  archive: { label: "Archive", icon: "archive", order: 7 },
51	};
52	
53	export function MailClient({
54	  initialFolders,
55	  initialMailboxes,
56	  initialList,
57	  initialFolderPath,
58	  initialSignature = "",
59	  initialActiveAddress,
60	}: {
61	  initialFolders: MailFolder[];
62	  initialMailboxes: MailboxInfo[];
63	  initialList: ListResult;
64	  initialFolderPath: string;
65	  initialSignature?: string;
66	  /**
67	   * Mailbox the server already loaded folders and messages for (the `?mailbox=`
68	   * deep link from a mailbox row on the Business Email page). It MUST match what
69	   * the server rendered: seeding this from anything else would show one
70	   * mailbox's messages under another mailbox's name until the first refetch.
71	   * The server only sets it after confirming the address belongs to this user.
72	   */
73	  initialActiveAddress?: string;
74	}) {
75	  const [folders, setFolders] = useState<MailFolder[]>(initialFolders);
76	  const [mailboxes, setMailboxes] = useState<MailboxInfo[]>(initialMailboxes);
77	  const [activeAddress, setActiveAddress] = useState<string | undefined>(
78	    initialActiveAddress ?? initialMailboxes[0]?.address,
79	  );
80	  const [selected, setSelected] = useState<string>(initialFolderPath);
81	  const [list, setList] = useState<ListResult>(initialList);
82	  const [page, setPage] = useState(1);
83	  const [tab, setTab] = useState<MailTab>("primary");
84	  const [search, setSearch] = useState("");
85	
86	  const [selectedUid, setSelectedUid] = useState<number | null>(null);
87	  const [cursorUid, setCursorUid] = useState<number | null>(null);
88	  const [message, setMessage] = useState<MessageFull | null>(null);
89	  const [msgLoading, setMsgLoading] = useState(false);
90	
91	  const [draft, setDraft] = useState<ComposeDraft | null>(null);
92	  const [sig, setSig] = useState<SigConfig>({
93	    enabled: true,
94	    onReply: true,
95	    placement: "below",
96	    plain: initialSignature,
97	    html: "",
98	  });
99	  const [showSettings, setShowSettings] = useState(false);
100	  const [mobilePane, setMobilePane] = useState<"list" | "read">("list");
101	  const [railOpen, setRailOpen] = useState(false);
102	  const [refreshing, setRefreshing] = useState(false);
103	  const [toast, setToast] = useState<string | null>(null);
104	  const [showHelp, setShowHelp] = useState(false);
105	
106	  // Collapsible panels — desktop only, persisted so the layout choice sticks.
107	  const [railCollapsed, setRailCollapsed] = useState(false);
108	  const [contactCollapsed, setContactCollapsed] = useState(false);
109	  useEffect(() => {
110	    try {
111	      if (localStorage.getItem("nxeon.mail.railCollapsed") === "1") setRailCollapsed(true);
112	      if (localStorage.getItem("nxeon.mail.contactCollapsed") === "1") setContactCollapsed(true);
113	    } catch {}
114	  }, []);
115	  const toggleRail = useCallback(() => {
116	    setRailCollapsed((v) => {
117	      const next = !v;
118	      try { localStorage.setItem("nxeon.mail.railCollapsed", next ? "1" : "0"); } catch {}
119	      return next;
120	    });
121	  }, []);
122	  const toggleContact = useCallback(() => {
123	    setContactCollapsed((v) => {
124	      const next = !v;
125	      try { localStorage.setItem("nxeon.mail.contactCollapsed", next ? "1" : "0"); } catch {}
126	      return next;
127	    });
128	  }, []);
129	
130	  const [listPending, startList] = useTransition();
131	  const searchTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
132	
133	  const mailbox = mailboxes.find((m) => m.address === activeAddress) ?? mailboxes[0] ?? null;
134	
135	  /* ---- Signature config (loaded per active mailbox) --------------------- */
136	  const loadSig = useCallback((addr?: string) => {
137	    getMailboxSettings(addr)
138	      .then((s) =>
139	        setSig({
140	          enabled: s.signatureEnabled,
141	          onReply: s.signatureOnReply,
142	          placement: s.signaturePlacement,
143	          plain: s.signature,
144	          html: s.signatureHtml,
145	        }),
146	      )
147	      .catch(() => {});
148	  }, []);
149	
150	  useEffect(() => {
151	    loadSig(activeAddress);
152	  }, [activeAddress, loadSig]);
153	
154	  /** Signature fields to spread into a compose draft, honouring the toggles. */
155	  const sigFields = useCallback(
156	    (isReply: boolean) => {
157	      if (!sig.enabled) return {};
158	      if (isReply && !sig.onReply) return {};
159	      return {
160	        signature: sig.plain || undefined,
161	        signatureHtml: sig.html || undefined,
162	        signaturePlacement: sig.placement,
163	      };
164	    },
165	    [sig],
166	  );
167	
168	  const inboxPath = folders.find((f) => f.role === "inbox")?.path ?? "INBOX";
169	  const archivePath = folders.find((f) => f.role === "archive")?.path;
170	  const trashPath = folders.find((f) => f.role === "trash")?.path;
171	
172	  /* ---- Rail model ------------------------------------------------------- */
173	  const byRole = (role: string) => folders.find((f) => f.role === role);
174	  const primaryItems: RailItem[] = [];
175	  const inbox = byRole("inbox");
176	  primaryItems.push({ key: inbox?.path ?? "INBOX", label: "Inbox", icon: "inbox", unread: inbox?.unread });
177	  primaryItems.push({ key: STARRED, label: "Starred", icon: "star", virtual: true });
178	  primaryItems.push({ key: SNOOZED, label: "Snoozed", icon: "clock", virtual: true });
179	  for (const role of ["sent", "drafts", "junk", "trash", "archive"] as const) {
180	    const f = byRole(role);
181	    const meta = ROLE_META[role];
182	    if (f) primaryItems.push({ key: f.path, label: meta.label, icon: meta.icon, unread: f.unread });
183	    else primaryItems.push({ key: `__missing_${role}`, label: meta.label, icon: meta.icon });
184	  }
185	  const customItems: RailItem[] = folders
186	    .filter((f) => f.role === "custom")
187	    .map((f) => ({ key: f.path, label: f.name, icon: "folder" as const, unread: f.unread }));
188	
189	  const labelFor = useCallback(
190	    (key: string): string => {
191	      if (key === STARRED) return "Starred";
192	      if (key === SNOOZED) return "Snoozed";
193	      const f = folders.find((x) => x.path === key);
194	      if (f) return ROLE_META[f.role]?.label ?? f.name;
195	      return "Mailbox";
196	    },
197	    [folders]
198	  );
199	
200	  const resolvePath = (key: string): string | null => {
201	    if (key === SNOOZED) return null;
202	    if (key === STARRED) return inboxPath;
203	    if (key.startsWith("__missing_")) return null;
204	    return key;
205	  };
206	
207	  /* ---- Loading ---------------------------------------------------------- */
208	  const loadList = useCallback(
209	    (key: string, pageNum: number, q: string, addr = activeAddress) => {
210	      const path = resolvePath(key);
211	      if (path === null) {
212	        setList({ messages: [], total: 0, page: 1, pageSize: initialList.pageSize });
213	        return;
214	      }
215	      startList(async () => {
216	        try {
217	          const res = await listMessages(path, pageNum, q || undefined, addr);
218	          if (key === STARRED) {
219	            const flagged = res.messages.filter((m) => m.flagged);
220	            setList({ messages: flagged, total: flagged.length, page: 1, pageSize: res.pageSize });
221	          } else {
222	            setList(res);
223	          }
224	        } catch {
225	          setToast("Couldn't load messages.");
226	        }
227	      });
228	    },
229	    [inboxPath, initialList.pageSize, activeAddress]
230	  );
231	
232	  const selectFolder = (key: string) => {
233	    setSelected(key);
234	    setPage(1);
235	    setRailOpen(false);
236	    setSelectedUid(null);
237	    setCursorUid(null);
238	    setMessage(null);
239	    setMobilePane("list");
240	    loadList(key, 1, search);
241	  };
242	
243	  /* ---- Mailbox switching ------------------------------------------------ */
244	  const switchMailbox = async (address: string) => {
245	    if (address === activeAddress) return;
246	    setActiveAddress(address);
247	    setSelectedUid(null);
248	    setCursorUid(null);
249	    setMessage(null);
250	    setMobilePane("list");
251	    setPage(1);
252	    setSearch("");
253	    setRailOpen(false);
254	    setRefreshing(true);
255	    try {
256	      const f = await listFolders(address);
257	      setFolders(f);
258	      const newInbox = f.find((x) => x.role === "inbox")?.path ?? f[0]?.path ?? "INBOX";
259	      setSelected(newInbox);
260	      loadList(newInbox, 1, "", address);
261	      // Refresh usage figures + the per-mailbox signature in the background —
262	      // never block the switch on either.
263	      void getMailboxes()
264	        .then((mb) => setMailboxes(Array.isArray(mb) ? mb : mb ? [mb] : []))
265	        .catch(() => {});
266	      // Signature config reloads via the activeAddress effect.
267	    } catch {
268	      setToast("Couldn't switch mailbox.");
269	    } finally {
270	      setRefreshing(false);
271	    }
272	  };
273	
274	  const openMessage = (m: MessageSummary) => {
275	    setSelectedUid(m.uid);
276	    setCursorUid(m.uid);
277	    setMobilePane("read");
278	    setMsgLoading(true);
279	    // Optimistically mark as read.
280	    if (!m.seen) {
281	      setList((cur) => ({ ...cur, messages: cur.messages.map((x) => (x.uid === m.uid ? { ...x, seen: true } : x)) }));
282	      setFolders((cur) => cur.map((f) => (f.path === m.folder ? { ...f, unread: Math.max(0, f.unread - 1) } : f)));
283	      void setFlag(m.folder, m.uid, "seen", true, activeAddress).catch(() => {});
284	    }
285	    (async () => {
286	      try {
287	        const full = await getMessage(m.folder, m.uid, activeAddress);
288	        setMessage(full);
289	      } catch {
290	        setToast("Couldn't open this message.");
291	        setMessage(null);
292	      } finally {
293	        setMsgLoading(false);
294	      }
295	    })();
296	  };
297	
298	  /* ---- Mutations -------------------------------------------------------- */
299	  const toggleStar = (m: MessageSummary | MessageFull) => {
300	    const next = !m.flagged;
301	    setList((cur) => ({ ...cur, messages: cur.messages.map((x) => (x.uid === m.uid ? { ...x, flagged: next } : x)) }));
302	    setMessage((cur) => (cur && cur.uid === m.uid ? { ...cur, flagged: next } : cur));
303	    if (selected === STARRED && !next) {
304	      // Un-starring inside the Starred view removes the row.
305	      setList((cur) => ({ ...cur, messages: cur.messages.filter((x) => x.uid !== m.uid), total: Math.max(0, cur.total - 1) }));
306	    }
307	    void setFlag(m.folder, m.uid, "flagged", next, activeAddress).catch(() => setToast("Couldn't update star."));
308	  };
309	
310	  const removeFromList = (m: MessageSummary | MessageFull) => {
311	    setList((cur) => ({ ...cur, messages: cur.messages.filter((x) => x.uid !== m.uid), total: Math.max(0, cur.total - 1) }));
312	    // Keep folder unread counts honest when an unread message leaves the folder.
313	    if (!m.seen) {
314	      setFolders((cur) => cur.map((f) => (f.path === m.folder ? { ...f, unread: Math.max(0, f.unread - 1) } : f)));
315	    }
316	    setSelectedUid(null);
317	    setCursorUid(null);
318	    setMessage(null);
319	    setMobilePane("list");
320	  };
321	
322	  const doArchive = () => {
323	    if (!message) return;
324	    const m = message;
325	    if (!archivePath || m.folder === archivePath) {
326	      setToast("No archive folder available.");
327	      return;
328	    }
329	    removeFromList(m);
330	    setToast("Message archived.");
331	    void moveMessage(m.folder, m.uid, archivePath, activeAddress).catch(() => setToast("Archive failed."));
332	  };
333	
334	  const doDelete = () => {
335	    if (!message) return;
336	    const m = message;
337	    removeFromList(m);
338	    // If already in trash, hard-delete; otherwise move to trash when possible.
339	    if (trashPath && m.folder !== trashPath) {
340	      setToast("Moved to Trash.");
341	      void moveMessage(m.folder, m.uid, trashPath, activeAddress).catch(() => setToast("Delete failed."));
342	    } else {
343	      setToast("Message deleted.");
344	      void deleteMessage(m.folder, m.uid, activeAddress).catch(() => setToast("Delete failed."));
345	    }
346	  };
347	
348	  const doMove = (toFolder: string) => {
349	    if (!message) return;
350	    const m = message;
351	    removeFromList(m);
352	    setToast(`Moved to ${labelFor(toFolder)}.`);
353	    void moveMessage(m.folder, m.uid, toFolder, activeAddress).catch(() => setToast("Move failed."));
354	  };
355	
356	  /* ---- Compose / reply -------------------------------------------------- */
357	  const stripRe = (s: string) => s.replace(/^\s*(re|fwd?):\s*/i, "").trim();
358	  const quoteOf = (m: MessageFull) =>
359	    m.html ??
360	    (m.text ? `<pre style="white-space:pre-wrap">${m.text.replace(/&/g, "&amp;").replace(/</g, "&lt;")}</pre>` : "");
361	
362	  // The signature is appended by the Composer (HTML part + plain-text part), so
363	  // new messages start with an empty body — the sig is no longer inlined into
364	  // the editable text.
365	  const openCompose = (to = "") =>
366	    setDraft({ mode: "new", to, cc: "", subject: "", body: "", ...sigFields(false) });
367	
368	  const openReply = (all: boolean) => {
369	    if (!message) return;
370	    const m = message;
371	    const selfAddr = mailbox?.address?.toLowerCase();
372	    const ccList = all
373	      ? [...m.to, ...m.cc].map((a) => a.address).filter((a) => a.toLowerCase() !== selfAddr && a.toLowerCase() !== m.from.address.toLowerCase())
374	      : [];
375	    setDraft({
376	      mode: all ? "replyAll" : "reply",
377	      to: m.from.address,
378	      cc: [...new Set(ccList)].join(", "),
379	      subject: `Re: ${stripRe(m.subject) || "(no subject)"}`,
380	      body: `\n\n`,
381	      quotedHtml: `<p>On ${new Date(m.date).toLocaleString()}, ${displayName(m.from)} wrote:</p>${quoteOf(m)}`,
382	      ...sigFields(true),
383	      inReplyToUid: m.uid,
384	      replyFolder: m.folder,
385	    });
386	  };
387	
388	  const openForward = () => {
389	    if (!message) return;
390	    const m = message;
391	    setDraft({
392	      mode: "forward",
393	      to: "",
