258	/** Bucket a (newest-first) list of messages into day groups, preserving order. */
259	function groupByDay(messages: MessageSummary[]): { label: string; items: MessageSummary[] }[] {
260	  const groups: { label: string; items: MessageSummary[] }[] = [];
261	  let current: { label: string; items: MessageSummary[] } | null = null;
262	  for (const m of messages) {
263	    const label = dayLabel(m.date);
264	    if (!current || current.label !== label) {
265	      current = { label, items: [] };
266	      groups.push(current);
267	    }
268	    current.items.push(m);
269	  }
270	  return groups;
271	}
