964	
965	function AutoReplySection({
966	  mailboxAddress,
967	  initial,
968	  onSaved,
969	}: {
970	  mailboxAddress?: string;
971	  initial: MailboxSettings;
972	  onSaved: (v: Partial<MailboxSettings>) => void;
973	}) {
974	  const [enabled, setEnabled] = useState(initial.autoReplyEnabled);
975	  const [subject, setSubject] = useState(initial.autoReplySubject);
976	  const [body, setBody] = useState(initial.autoReplyBody);
977	  const [start, setStart] = useState(initial.autoReplyStart);
978	  const [end, setEnd] = useState(initial.autoReplyEnd);
979	  const [saving, setSaving] = useState(false);
980	  const [msg, setMsg] = useState<string | null>(null);
981	  const [err, setErr] = useState<string | null>(null);
982	  const [bump, setBump] = useState(0);
983	  const { status, loading } = useRuleStatus(mailboxAddress, bump);
984	
985	  async function save() {
986	    setSaving(true);
987	    setMsg(null);
988	    setErr(null);
989	    try {
990	      const res = await saveAutoReply({ enabled, subject, body, start, end }, mailboxAddress);
991	      if (!res.ok) setErr(res.error || "Couldn't save.");
992	      else {
993	        // "Applied." not "Saved.": saveAutoReply pushes sieve to the mail server
994	        // BEFORE it writes the DB and returns an error if that push fails, so
995	        // reaching here means the server accepted the rule.
996	        setMsg("Applied.");
997	        setBump((v) => v + 1);
998	        onSaved({
999	          autoReplyEnabled: enabled,
1000	          autoReplySubject: subject.trim(),
1001	          autoReplyBody: body.trim(),
1002	          autoReplyStart: start,
1003	          autoReplyEnd: end,
1004	        });
1005	      }
1006	    } catch (e) {
1007	      setErr(e instanceof Error ? e.message : "Couldn't save.");
1008	    } finally {
1009	      setSaving(false);
1010	    }
1011	  }
1012	
1013	  return (
1014	    <div className="space-y-5">
1015	      <SectionHead title="Auto-reply" sub="Send an automatic response to incoming messages while you're away." />
1016	
1017	      <Toggle label={`Auto-reply ${enabled ? "on" : "off"}`} checked={enabled} onChange={() => setEnabled((v) => !v)} />
1018	
1019	      <div className={enabled ? "space-y-4" : "space-y-4 opacity-50"}>
1020	        <div>
1021	          <label className="label" htmlFor="ar-subject">Subject</label>
1022	          <input
1023	            id="ar-subject"
1024	            className="input"
1025	            value={subject}
1026	            onChange={(e) => setSubject(e.target.value)}
1027	            placeholder="Out of office"
1028	            maxLength={200}
1029	            disabled={!enabled}
1030	          />
1031	        </div>
1032	        <div>
1033	          <label className="label" htmlFor="ar-body">Message</label>
1034	          <textarea
1035	            id="ar-body"
1036	            className="input min-h-[8rem] resize-y leading-relaxed"
1037	            value={body}
1038	            onChange={(e) => setBody(e.target.value)}
1039	            placeholder="Thanks for your email. I'm away until…"
1040	            maxLength={5000}
1041	            disabled={!enabled}
1042	          />
1043	        </div>
1044	        <div className="grid gap-3 sm:grid-cols-2">
1045	          <div>
1046	            <label className="label" htmlFor="ar-start">Only send from</label>
1047	            <input
1048	              id="ar-start"
1049	              type="date"
1050	              className="input"
1051	              value={start}
1052	              onChange={(e) => setStart(e.target.value)}
1053	              disabled={!enabled}
1054	            />
1055	          </div>
1056	          <div>
1057	            <label className="label" htmlFor="ar-end">Until</label>
1058	            <input
1059	              id="ar-end"
1060	              type="date"
1061	              className="input"
1062	              value={end}
1063	              onChange={(e) => setEnd(e.target.value)}
1064	              disabled={!enabled}
1065	            />
1066	          </div>
1067	        </div>
1068	        <p className="text-xs text-slate-500">Leave the dates blank to keep the auto-reply active with no end date.</p>
1069	      </div>
1070	
1071	      <RuleStatusNote
1072	        status={status}
1073	        loading={loading}
1074	        live={Boolean(status?.autoReplyLive)}
1075	        // Compared against the PERSISTED values, not the form state: flipping the
1076	        // toggle without saving must not accuse the mail server of ignoring a
1077	        // rule that was never sent to it. `initial` is patched after a save.
1078	        savedOn={initial.autoReplyEnabled && initial.autoReplyBody.trim().length > 0}
1079	        runningText="Replies are sent by the mail server, so they keep going out while you're offline — and only once per sender per day."
1080	      />
1081	
1082	      <SaveRow saving={saving} msg={msg} err={err} onSave={save} />
1083	    </div>
1084	  );
1085	}
