475	      from: displayName ? { name: displayName, address: cred.address } : cred.address,
476	      replyTo: replyTo || undefined,
477	      to: to.list,
478	      cc: cc.list.length ? cc.list : undefined,
479	      bcc: bcc.list.length ? bcc.list : undefined,
480	      subject: payload.subject || "",
481	      text: payload.text || undefined,
482	      html: payload.html || undefined,
483	      attachments: attachments.length ? attachments : undefined,
484	      inReplyTo,
485	      references,
486	      headers: organization ? { Organization: organization } : undefined,
487	    });
488	    const raw = built.message as Buffer;
489	
490	    const smtp = nodemailer.createTransport({
491	      host: MAIL_SMTP_HOST,
492	      port: MAIL_SMTP_PORT,
493	      secure: MAIL_SMTP_PORT === 465,
494	      requireTLS: MAIL_SMTP_PORT !== 465,
495	      tls: { servername: MAIL_TLS_SERVERNAME, rejectUnauthorized: false },
496	      auth: { user: cred.address, pass: cred.password },
