export async function listAliases(
  mailboxAddress?: string,
): Promise<{ ok: boolean; error?: string; aliases: AliasRow[] }> {
  const { user, address } = await resolveMailbox(mailboxAddress);
  const domain = domainOf(address);
  if (!mailcowConfigured()) return { ok: false, error: "Mail server is not configured yet.", aliases: [] };

  const owned = await ownedDomains(user.id);
  if (!owned.has(domain)) return { ok: false, error: "You don't own this mailbox's domain.", aliases: [] };

  try {
    const list = await mcListAliases(domain);
    return { ok: true, aliases: toAliasRows(list) };
  } catch (e) {
    return { ok: false, error: friendly(e), aliases: [] };
  }
}

/**
 * Add an alias on a domain the caller owns. `alias` may be a full address or a
 * bare local part (the mailbox's own domain is assumed). `goto` defaults to the
 * mailbox itself.
 */
export async function addAlias(alias: string, goto?: string, mailboxAddress?: string): Promise<Result> {
  const { user, address } = await resolveMailbox(mailboxAddress);
  const limited = gate(`mail:alias:${user.id}`, 20, 60_000);
  if (limited) return limited;
  if (!mailcowConfigured()) return { ok: false, error: "Mail server is not configured yet." };

  let aliasAddr = (alias ?? "").trim().toLowerCase();
  if (!aliasAddr) return { ok: false, error: "Enter an alias address." };
  // Accept a bare local part — assume the mailbox's own domain.
  if (!aliasAddr.includes("@")) aliasAddr = `${aliasAddr}@${domainOf(address)}`;
  if (!EMAIL_RE.test(aliasAddr)) return { ok: false, error: "That doesn't look like a valid email address." };

  const owned = await ownedDomains(user.id);
  if (!owned.has(domainOf(aliasAddr))) {
    return { ok: false, error: "You can only add aliases on a domain you own." };
  }

  const dest = (goto ?? "").trim() || address;
  if (!EMAIL_RE.test(dest)) return { ok: false, error: "The destination address is not valid." };
  if (dest.toLowerCase() === aliasAddr) return { ok: false, error: "An alias can't point to itself." };

  try {
    await mcAddAlias(aliasAddr, dest);
    return { ok: true };
  } catch (e) {
    return { ok: false, error: friendly(e) };
  }
}

/** Remove an alias by id, after verifying it lives on a domain the caller owns. */
export async function removeAlias(id: number, mailboxAddress?: string): Promise<Result> {
  const { user, address } = await resolveMailbox(mailboxAddress);
  const limited = gate(`mail:alias:${user.id}`, 20, 60_000);
  if (limited) return limited;
  if (!mailcowConfigured()) return { ok: false, error: "Mail server is not configured yet." };
  if (!Number.isFinite(id)) return { ok: false, error: "Invalid alias." };

  const domain = domainOf(address);
  const owned = await ownedDomains(user.id);
  if (!owned.has(domain)) return { ok: false, error: "You don't own this mailbox's domain." };

  try {
    // Confirm the alias belongs to this owned domain before deleting.
    const list = await mcListAliases(domain);
    const match = list.find((a) => a.id === id);
    if (!match) return { ok: false, error: "That alias no longer exists on your domain." };
    await mcDeleteAlias(id);
    return { ok: true };
  } catch (e) {
    return { ok: false, error: friendly(e) };
  }
}

